import * as path from 'path';

// One comment block that exceeds the limit. `lines` counts comment lines only;
// blank lines inside the block are not counted and do not end it.
export interface CommentBlock {
	startLine: number;
	endLine: number;
	lines: number;
}

// The limit, in comment lines. Deliberately a constant with no input: a
// settable maximum removes the rule instead of configuring it.
export const MAX_COMMENT_LINES = 1;

function isCommentLine(line: string): boolean {
	return line.trimStart().startsWith('#');
}

// Every comment block in the file that runs past the limit. see README.md
export function findCommentBlocks(content: string, max: number = MAX_COMMENT_LINES): CommentBlock[] {
	const lines = content.split(/\r?\n/);
	const blocks: CommentBlock[] = [];
	let start = -1;
	let count = 0;
	let end = -1;

	const flush = (): void => {
		if (count > max) {
			blocks.push({startLine: start + 1, endLine: end + 1, lines: count});
		}
		start = -1;
		count = 0;
		end = -1;
	};

	lines.forEach((line, index) => {
		if (isCommentLine(line)) {
			if (count === 0) {
				start = index;
			}
			count++;
			end = index;
			return;
		}
		if (line.trim() === '') {
			return;
		}
		if (count > 0) {
			flush();
		}
	});
	if (count > 0) {
		flush();
	}
	return blocks;
}

export interface UsesRef {
	value: string;
	line: number;
}

// Every `uses:` value in a workflow or action file, with its line number.
// A regex, not a YAML walk: a `uses:` key means the same thing at every depth
// (workflow job, workflow step, composite step), and a file this action
// rejects may also be a file the YAML parser rejects.
export function findUses(content: string): UsesRef[] {
	const refs: UsesRef[] = [];
	content.split(/\r?\n/).forEach((line, index) => {
		// An unquoted value ends at whitespace, not at `#`: a `#` with no space
		// before it is part of the scalar, which is how this repo's own refs
		// are spelled (`wow-look-at-my/actions@typescript#latest`).
		const match = /^\s*(?:-\s+)?uses:\s*(?:'([^']*)'|"([^"]*)"|(\S+))/.exec(line);
		if (!match) {
			return;
		}
		const value = match[1] ?? match[2] ?? match[3] ?? '';
		if (value !== '') {
			refs.push({value, line: index + 1});
		}
	});
	return refs;
}

// True for a `uses:` value that names a file in this repository. Everything
// else lives in another repository and cannot be read from the workspace.
export function isLocalRef(value: string): boolean {
	return value.startsWith('./');
}

// The workspace-relative paths a local `uses:` value can resolve to. A
// reusable workflow names its file directly; a composite or Node action names
// its directory, and the action file is `action.yml` or `action.yaml`.
export function candidatePaths(value: string): string[] {
	const target = path.posix.normalize(value.replace(/^\.\//, ''));
	if (/\.ya?ml$/.test(target)) {
		return [target];
	}
	return [path.posix.join(target, 'action.yml'), path.posix.join(target, 'action.yaml')];
}

export function formatBlock(file: string, block: CommentBlock, max: number = MAX_COMMENT_LINES): string {
	const span = block.startLine === block.endLine ? `line ${block.startLine}` : `lines ${block.startLine}-${block.endLine}`;
	return (
		`${file}: ${block.lines} comment lines in a row (${span}) — the limit is ${max}. ` +
		`Shorten this to one line. Say only what a reader needs right here.`
	);
}
